corrected_code:
package storage

import (
	"net/http"
	"github.com/golang-jwt/jwt/v5"
	"github.com/labstack/echo/v4"
	"myapp/cloud"
)

type BucketPolicyBody struct {
	IsPublic bool `json:"is_public"`
}

type BucketHandler struct {
	CloudStorage cloud.StorageService
}

func (h *BucketHandler) SetBucketPolicy(c echo.Context) error {
	bucketID := c.Param("bucketID")
	token := c.Get("user").(*jwt.Token)
	claims := token.Claims.(jwt.MapClaims)
	callerTenantID := claims["tenant_id"].(string)

	var body BucketPolicyBody
	if err := c.Bind(&body); err != nil {
		return c.JSON(http.StatusBadRequest, echo.Map{"error": err.Error()})
	}

	err := h.CloudStorage.UpdatePolicyForTenant(c.Request().Context(), bucketID, callerTenantID, body.IsPublic)
	if err != nil {
		return c.JSON(http.StatusForbidden, echo.Map{"error": "Access denied or bucket not found"})
	}

	return c.JSON(http.StatusOK, echo.Map{"success": true})
}
